package main

import (
	"fmt"
)

// Bind to stable Slot identities, including waiting Slots without a hostname.
// Existing ports, clients and keys are never regenerated by reconciliation.
func (n *Native) ensureSlotInbounds(tunnels []*Tunnel, serverName string) error {
	n.mu.Lock()
	defer n.mu.Unlock()
	finish := n.beginChange()
	defer finish()
	changed := false
	used := n.store.usedPorts()
	checkedReality := false
	// A restored Slot can already be dialing a new host while its legacy
	// inbound still names the previous host. Migrate all previous bindings
	// first, before another Slot can reuse that hostname or create a duplicate.
	previous, current := map[string]int{}, map[string]int{}
	put := func(table map[string]int, host string, slot int) {
		if host == "" {
			return
		}
		host = sanitizeTag(host)
		if old, ok := table[host]; ok && old != slot {
			table[host] = 0
		} else {
			table[host] = slot
		}
	}
	for _, t := range tunnels {
		t.mu.Lock()
		put(previous, t.prevHost, t.Slot)
		put(current, t.Node.HostName, t.Slot)
		t.mu.Unlock()
	}
	for _, ib := range n.store.Inbounds {
		if ib.BoundSlot != 0 || ib.BoundTo == "" {
			continue
		}
		slot, ok := previous[ib.BoundTo]
		if !ok {
			slot, ok = current[ib.BoundTo]
		}
		if !ok {
			continue
		}
		if slot == 0 {
			return fmt.Errorf("旧入站绑定存在多个出口身份，保留配置等待明确绑定")
		}
		ib.BoundSlot = slot
		changed = true
	}
	for _, t := range tunnels {
		v := t.snapshot()
		found := false
		for _, ib := range n.store.Inbounds {
			if ib.BoundSlot == v.Slot {
				found = true
				break
			}
		}
		if found {
			continue
		}
		if !checkedReality {
			if err := checkRealityDest(serverName+":443", serverName); err != nil {
				return fmt.Errorf("REALITY 目标站点不可用: %w", err)
			}
			checkedReality = true
		}
		port := 30000 + v.Slot
		if used[port] || !portAvailable(port) {
			var err error
			port, err = freeRandomPort(used)
			if err != nil {
				return err
			}
		}
		ib, err := n.prepareInbound(NewInboundSpec{realityChecked: true, Protocol: "vless", Network: "tcp", Security: "reality", Port: port,
			Remark: fmt.Sprintf("出口 %02d", v.Slot), Dest: serverName + ":443", ServerNames: serverName, Fingerprint: "chrome"}, used)
		if err != nil {
			return err
		}
		ib.BoundSlot, ib.NameMode = v.Slot, "auto"
		if v.Node.HostName != "" {
			ib.BoundTo = sanitizeTag(v.Node.HostName)
		}
		n.store.NextID++
		n.store.Inbounds = append(n.store.Inbounds, ib)
		used[port], changed = true, true
	}
	if changed {
		return n.apply(tunnels)
	}
	return nil
}

func automaticName(ib ExitInbound) bool {
	return inboundNameMode(ib.NameMode, ib.Remark) == "auto"
}

func inboundNameMode(mode, remark string) string {
	if mode != "" {
		return mode
	}
	if remark == "" || isGeneratedLabel(remark) || isLegacySlotName(remark) {
		return "auto"
	}
	return "custom"
}

// Old standalone installs used slot-01..32 before name_mode existed. Only
// these exact placeholders are inferred; an explicit custom mode always wins.
func isLegacySlotName(remark string) bool {
	for slot := 1; slot <= maximumSlots; slot++ {
		if remark == fmt.Sprintf("slot-%02d", slot) {
			return true
		}
	}
	return false
}

func subscriptionExitName(e Exit) string {
	country := "待验证"
	if e.Status == "up" && e.Egress != nil && e.Egress.IntelligenceStatus == "passed" && flagOf(stringValue(e.Egress.Country)) != "" {
		country = countryLabel(stringValue(e.Egress.Country), stringValue(e.Egress.Country))
	}
	return fmt.Sprintf("%s · %02d", country, e.Slot)
}
